import express from 'express';
const app = express();
app.use(express.json());

const users: any[] = [];

app.get('/users', (req, res) => { res.json(users); });
app.post('/users', (req, res) => { users.push(req.body); res.status(201).json(req.body); });
app.get('/users/:id', (req, res) => { const user = users.find(u => u.id === req.params.id); if (user) res.json(user); else res.status(404).json({ error: 'Not found' }); });
app.delete('/users/:id', (req, res) => { const index = users.findIndex(u => u.id === req.params.id); if (index !== -1) { users.splice(index, 1); res.status(204).send(); } else { res.status(404).json({ error: 'Not found' }); } });

app.listen(3000);
